import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput';
import { ZimmModal } from 'app/components/ui-kits/atoms/zimmModal';
import { isSafeHref } from 'app/utils/safeHref';
import { useZimmModal } from 'app/hooks/useZimmModal';

const ZIMM_SUBSCRIBE_MODAL_RECIPE = 'ZimmSubscribeModal';
const ZIMM_MODAL_RECIPE = 'ZimmModal';
// alias/size/modal/footer (480px). Provisional — kept as a named rem reference until the UI
// designer confirms a shared modal-size token; every dialog built on ZimmModal supplies its own
// maxWidth today rather than inheriting a guessed default.
const MODAL_MAX_WIDTH = '30rem';

// HPC-037 copy — update when UX supplies final content.
const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
const ACCESSIBILITY_DISCLAIMER_COPY =
  'Zimmermann is committed to providing accessible services. ' +
  'If you experience any difficulty, please contact us for assistance.';

type ZimmSubscribeModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (firstName: string, lastName: string) => void;
  privacyPolicyHref: string;
};

/**
 * The HPC-035 first/last-name capture modal, built on the generic ZimmModal atom. Rendered
 * through a portal (via ZimmModal) so the overlay escapes the caller's stacking context.
 *
 * @param props see ZimmSubscribeModalProps
 */
export const ZimmSubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: ZimmSubscribeModalProps) => {
  const { mounted, trapRef, firstFocusRef } = useZimmModal({ isOpen, onClose });
  const chrome = useMultiStyleConfig(ZIMM_MODAL_RECIPE, {});
  const styles = useMultiStyleConfig(ZIMM_SUBSCRIBE_MODAL_RECIPE, {});

  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    // namedItem returns Element | RadioNodeList | null. The cast keeps `| null` rather than
    // asserting it away — these fields are always single <input>s rendered by ZimmTextInput,
    // but a missing field must stay a null the `?.` below can actually catch. Same pattern as
    // zimmInputAction's handleSubmit.
    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement | null)?.value ?? '';
    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement | null)?.value ?? '';
    onSubmit(firstName.trim(), lastName.trim());
  };

  return (
    <ZimmModal
      isOpen={isOpen}
      mounted={mounted}
      onClose={onClose}
      maxWidth={MODAL_MAX_WIDTH}
      labelledBy="zimm-subscribe-modal-title"
      describedBy="zimm-subscribe-modal-consent"
    >

